import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Desktop calendar connector: platform fit across macOS, Windows, Linux","description":"","frontmatter":{"id":11,"title":"Desktop calendar connector: platform fit across macOS, Windows, Linux","status":"decided","date":"August 2026","author":"Claude Code (session with the developer)","scope":"shared","summary":"Extending the Calendar connector (research 0005) to desktop — which OS calendar APIs are actually reachable from an unpackaged Tauri app","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/research/0011-desktop-calendar-connector.md"},"headers":[],"relativePath":"sovereign-edge/research/0011-desktop-calendar-connector.md","filePath":"sovereign-edge/research/0011-desktop-calendar-connector.md"}'),i={name:"sovereign-edge/research/0011-desktop-calendar-connector.md"};function s(r,e,c,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="research-0011-—-desktop-calendar-connector-platform-fit-across-macos-windows-linux" tabindex="-1">Research 0011 — Desktop calendar connector: platform fit across macOS, Windows, Linux <a class="header-anchor" href="#research-0011-—-desktop-calendar-connector-platform-fit-across-macos-windows-linux" aria-label="Permalink to &quot;Research 0011 — Desktop calendar connector: platform fit across macOS, Windows, Linux&quot;">​</a></h1><p><strong>Related:</strong> <a href="./../epics/mobile/calendar-connector.html">Calendar Connector</a> (task 10.1, mobile), <a href="./0005-calendar-connector.html">research 0005</a> (the mobile scoping this extends), <a href="./../epics/desktop/core-port.html">Desktop Core Port</a></p><hr><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p>The user asked for the Calendar connector on both mobile and desktop. Mobile&#39;s answer (<code>expo-calendar</code>, uniform on iOS/Android) has no desktop equivalent — what does each desktop OS actually offer, and is any of it reachable from this app&#39;s real distribution shape (an unpackaged Tauri binary, NSIS/MSI on Windows, no MSIX)?</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><ul><li><strong>macOS — real, fully reachable.</strong> Apple&#39;s EventKit framework (<code>EKEventStore</code>) is directly callable via <code>objc2-event-kit</code>, part of the well-established <code>objc2</code> project. No package-identity requirement, no shell-out. <code>objc2</code> itself (<code>0.6.4</code>) and <code>objc2-foundation</code> were already transitive dependencies of this app via Tauri&#39;s own macOS backend, confirmed by reading <code>Cargo.lock</code> before adding anything — this is not a novel FFI surface for the dependency graph, only for this app&#39;s own code. This is the only OS this development environment can actually build and verify (a real debug binary build + launch-smoke check, task 10.2&#39;s own verification).</li><li><strong>Windows — real API exists, but not reachable from this app&#39;s actual distribution shape.</strong> <code>windows::ApplicationModel::Appointments:: AppointmentStore</code> (the official <code>windows</code> crate, Microsoft&#39;s own WinRT Calendar API) requires <strong>package identity</strong> — confirmed via Microsoft&#39;s own documentation on <code>APPMODEL_ERROR_NO_PACKAGE</code>/<code>E_ILLEGAL_METHOD_CALL</code>. This app ships as an unpackaged NSIS/MSI installer (task 14&#39;s own distribution model, no MSIX), so calling this API today would fail at runtime. The two ways around it — packaging with a sparse/external-location package to gain identity without moving to full MSIX, or falling back to Outlook COM automation (works unpackaged, but only if Outlook happens to be installed, an assumption this app makes nowhere else) — are both real scope, not a small addition, and neither was picked for this pass.</li><li><strong>Linux — no single API to target.</strong> GNOME&#39;s calendar/contacts stack (<code>evolution-data-server</code>) exposes its own D-Bus interface (<code>org.gnome.evolution.dataserver.Calendar</code>); KDE&#39;s Akonadi is a structurally different protocol (its own D-Bus + local-socket IMAP-like layer, per Akonadi&#39;s own architecture docs), not a thin skin over EDS. Genuine support means picking one backend (most plausibly GNOME/EDS, since it&#39;s the more standardized of the two) and documenting KDE/other desktop environments as unsupported — a real per-desktop-environment support matrix, not a single implementation.</li><li><strong>No Rust crate in this repo&#39;s dependency graph today bridges any of the above except the macOS one</strong> — <code>keyring</code>&#39;s existing <code>[target.&#39;cfg(target_os = &quot;...&quot;)&#39;.dependencies]</code> blocks in <code>Cargo.toml</code> were the only precedent for platform-conditional native dependencies before this task, and only the macOS block gained new dependencies (<code>objc2</code>, <code>objc2-event-kit</code>, <code>objc2-foundation</code>, <code>block2</code>).</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>macOS now, via real EventKit bindings; Windows and Linux stay unsupported for this pass, documented here rather than silently dropped.</strong> Confirmed with the user directly (not inferred) — the alternative of researching all three before writing any code, chosen explicitly over shipping macOS alone without the comparison, or attempting all three unverified.</p><p><code>known_connector_manifests()</code> (<code>apps/desktop/src-tauri/src/lib.rs</code>) only includes the four calendar manifests when <code>cfg!(target_os = &quot;macos&quot;)</code> — via <code>connectors::calendar::calendar_manifests()</code> itself returning an empty <code>Vec</code> off macOS, not a call-site <code>cfg!</code> — so a Windows or Linux build never advertises a connector it can&#39;t run; this needed no manifest schema change (desktop&#39;s <code>platforms: [&quot;desktop&quot;]</code> value is already OS-agnostic by design, matching mobile&#39;s <code>[&quot;ios&quot;,&quot;android&quot;]</code> — see the Calendar SDK&#39;s own schema comment) — it needed a Rust-side scoping decision instead.</p><h2 id="open-questions-for-whoever-picks-windows-linux-up-next" tabindex="-1">Open questions for whoever picks Windows/Linux up next <a class="header-anchor" href="#open-questions-for-whoever-picks-windows-linux-up-next" aria-label="Permalink to &quot;Open questions for whoever picks Windows/Linux up next&quot;">​</a></h2><ul><li><strong>Windows:</strong> does adopting a sparse/external-location package (identity without full MSIX) conflict with anything in the existing NSIS/MSI release pipeline (<code>.github/workflows/desktop-release.yml</code>)? Not evaluated here — this decision was scoped to &quot;is EventKit reachable today,&quot; not &quot;redesign desktop&#39;s packaging model.&quot;</li><li><strong>Linux:</strong> GNOME/EDS only, or attempt a KDE/Akonadi backend too? EDS-only is the pragmatic default (GNOME&#39;s stack is closer to a stable public API surface than Akonadi&#39;s), but this wasn&#39;t decided here, only flagged as the fork whoever picks this up will hit first.</li></ul>',12)])])}const f=o(i,[["render",s]]);export{u as __pageData,f as default};
